CREATE TABLE scheduled_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), owner_id uuid NOT NULL, report_key varchar(80) NOT NULL, cadence varchar(40) NOT NULL CHECK(cadence IN ('daily','weekly','monthly')), format varchar(10) NOT NULL CHECK(format IN ('csv','xlsx','pdf')), recipients jsonb NOT NULL, filters jsonb NOT NULL DEFAULT '{}'::jsonb, timezone varchar(80) NOT NULL DEFAULT 'UTC', next_run_at timestamptz NOT NULL, active integer NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT scheduled_reports_owner_fk FOREIGN KEY(tenant_id,owner_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE INDEX scheduled_reports_owner_idx ON scheduled_reports(tenant_id,owner_id);
CREATE TABLE scheduled_report_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), schedule_id uuid NOT NULL REFERENCES scheduled_reports(id) ON DELETE CASCADE, status varchar(20) NOT NULL, started_at timestamptz NOT NULL, completed_at timestamptz, error varchar(1000), row_count integer);
CREATE INDEX scheduled_report_deliveries_idx ON scheduled_report_deliveries(tenant_id,schedule_id,started_at);
